  const formatErrors = []; if (!validateField(document.getElementById('order-name'), 'name')) { setFieldError('order-name', 'order-name-error', VALIDATORS.name.message); formatErrors.push('ad'); } if (!validateField(document.getElementById('order-email'), 'email')) { setFieldError('order-email', 'order-email-error', VALIDATORS.email.message); formatErrors.push('e-posta'); } if (!validateField(document.getElementById('order-phone'), 'phone')) { setFieldError('order-phone', 'order-phone-error', VALIDATORS.phone.message); formatErrors.push('telefon'); } if (formatErrors.length > 0) { showToast(`Lütfen ${formatErrors.join(', ')} alanlarını doğru formatta doldurun.`, 'error'); return; } if (state.checkoutPaymentMethod === 'iyzico') { 
    const cardErrors = []; const cardFields = [ ['cc-number', 'cc-number-error', 'card', 'Kart numarası'], ['cc-expiry', 'cc-expiry-error', 'expiry', 'Son kullanma tarihi'], ['cc-cvv', 'cc-cvv-error', 'cvv', 'CVV'] ]; cardFields.forEach(([inputId, errorId, type, label]) => { const input = document.getElementById(inputId); const value = input ? input.value.trim() : ''; if (!value) { setFieldError(inputId, errorId, `${label} alanı boş bırakılamaz.`); cardErrors.push(label); return; } if (!validateField(input, type)) { setFieldError(inputId, errorId, VALIDATORS[type].message); cardErrors.push(label); } }); const ccName = document.getElementById('cc-name'); if (ccName && ccName.value.trim().length < 3) { setFieldError('cc-name', 'cc-name-error', 'Kart sahibinin adı soyadı girilmeli.'); cardErrors.push('Kart sahibi'); } if (cardErrors.length > 0) { showToast(`Lütfen ${cardErrors.join(', ')} alan(lar)ını eksiksiz ve doğru doldurun.`, 'error'); return; } open3DSecureModal({ fullName, email, phone, city, district, address, note }); return; } finalizeOrder({ fullName, email, phone, city, district, address, note });
